mapper.select:
SELECT e.*
FROM session_events e
WHERE e.app_name = #{appName}
  AND e.user_id = #{userId}
  AND e.session_id = #{sessionId}
ORDER BY e.id ASC

SELECT recent.*
FROM (
    SELECT e.*
    FROM session_events e
    WHERE e.app_name = #{appName}
      AND e.user_id = #{userId}
      AND e.session_id = #{sessionId}
    ORDER BY e.id DESC
    LIMIT #{limit}
) recent
ORDER BY recent.id ASC

SELECT e.*
FROM session_events e
WHERE e.app_name = #{appName}
  AND e.user_id = #{userId}
  AND e.session_id = #{sessionId}
  AND e.event_ts > #{afterTimestamp}
ORDER BY e.id ASC

